pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // keep _changeFee admissible: adding 1 must not overflow uint56, so the
        // buggy version stores a well-defined (but wrong) value.
        vm.assume(_changeFee < type(uint56).max);
        vm.assume(_feeRate <= 5_000);

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        // General rule: initialize stores changeFee exactly as provided.
        assertTrue(c.changeFee() == _changeFee);
    }
}

